import json
from typing import Any, Dict, Optional, Union, List

def validate_json(data: Any, schema: Dict) -> Optional[str]:
    stype = schema.get("type")
    type_map = {"object": dict, "array": list, "string": str,
                "number": (int, float), "integer": int, "boolean": bool, "null": type(None)}
    expected = type_map.get(stype)
    if expected and not isinstance(data, expected):
        return f"Expected {stype}, got {type(data).__name__}"

    if stype == "object" and "properties" in schema:
        if not isinstance(data, dict):
            return f"Expected object"
        for key, prop_schema in schema["properties"].items():
            if key in data:
                err = validate_json(data[key], prop_schema)
                if err:
                    return f"{key}: {err}"
            elif key in schema.get("required", []):
                return f"Missing required field: {key}"
        if "additionalProperties" in schema and schema["additionalProperties"] is False:
            extra = set(data.keys()) - set(schema.get("properties", {}).keys())
            if extra:
                return f"Unexpected fields: {extra}"
    elif stype == "array" and "items" in schema:
        if not isinstance(data, list):
            return f"Expected array"
        for i, item in enumerate(data):
            err = validate_json(item, schema["items"])
            if err:
                return f"[{i}]: {err}"
    return None
